/**
 * fix_sounds_json.mjs
 *
 * Post-processes the sounds.json generated by audiosprite to match the format
 * expected by pixi-svelte / utils-sound (Howler sprite format with `src`, loop
 * flags on BGM/loop tracks, and a `config` volume block).
 *
 * Run AFTER audiosprite:
 *   node fix_sounds_json.mjs
 */

import { readFileSync, writeFileSync } from 'fs';
import { resolve, dirname } from 'path';
import { fileURLToPath } from 'url';

const __dirname = dirname(fileURLToPath(import.meta.url));
const jsonPath = resolve(__dirname, '../sounds.json');

const LOOP_SOUNDS = new Set([
	'bgm_main',
	'bgm_bonus_intro',
	'bgm_freespin',
	'bgm_winlevel_big',
	'bgm_winlevel_epic',
	'bgm_winlevel_max',
	'bgm_winlevel_mega',
	'bgm_winlevel_superwin',
	'sfx_bigwin_coinloop',
]);

const raw = JSON.parse(readFileSync(jsonPath, 'utf8'));

// 1. Rename "urls" → "src" and fix relative paths to absolute web paths
const urls = raw.urls ?? raw.src;
const src = (Array.isArray(urls) ? urls : [urls]).map((u) =>
	u.replace(/^\.\.\/sounds/, './assets/audio/sounds'),
);

// 2. Add loop flags (true) for looping sounds in the sprite map
const sprite = {};
for (const [name, entry] of Object.entries(raw.sprite)) {
	sprite[name] = LOOP_SOUNDS.has(name)
		? [entry[0], entry[1], true]   // [start, duration, loop]
		: [entry[0], entry[1]];        // [start, duration]
}

// 3. Build config block (vol = 1 for all)
const config = Object.fromEntries(Object.keys(sprite).map((k) => [k, { volume: 1 }]));

// 4. Write corrected JSON (drop "urls", keep only "src"/"sprite"/"config")
const output = { src, sprite, config };
writeFileSync(jsonPath, JSON.stringify(output, null, '\t') + '\n', 'utf8');

console.log(`✅  sounds.json fixed: ${Object.keys(sprite).length} sprites, ${src.length} src files`);
console.log('   Loop sounds:', [...LOOP_SOUNDS].filter((n) => sprite[n]).join(', '));
